function validate([words]) {
  if (words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  if (words.some(w => w.length < 1 || w.length > 1000)) return 'Each word has 1 to 1000 letters.';
  if (words.some(w => !/^[a-z]+$/.test(w))) return 'Words use only lowercase English letters.';
  return null;
}

