function sumPrefixScores(words) {
  const root = { count: 0, children: new Map() };
  for (const word of words) {
    let node = root;
    for (const letter of word) {
      if (!node.children.has(letter)) {
        node.children.set(letter, { count: 0, children: new Map() });
      }
      node = node.children.get(letter);
      node.count++;
    }
  }
  const answer = [];
  for (const word of words) {
    let node = root;
    let total = 0;
    for (const letter of word) {
      node = node.children.get(letter);
      total += node.count;
    }
    answer.push(total);
  }
  return answer;
}

