function sumPrefixScores(words) {
  return words.map(word => {
    let total = 0;
    for (let length = 1; length <= word.length; length++) {
      const prefix = word.slice(0, length);
      total += words.filter(other => other.startsWith(prefix)).length;
    }
    return total;
  });
}

