function generate(rand, size) {
  const word = (alphabet, maxLength) => {
    const length = 1 + Math.floor(rand() * maxLength);
    let text = '';
    for (let k = 0; k < length; k++) text += alphabet[Math.floor(rand() * alphabet.length)];
    return text;
  };
  if (size === 'large') {
    if (rand() < 0.5) return [Array.from({ length: 1000 }, () => word('abc', 30))];
    const stem = 'q'.repeat(600);
    return [Array.from({ length: 20 }, () => stem + word('xy', 400))];
  }
  const alphabet = rand() < 0.5 ? 'ab' : 'abcz';
  return [Array.from({ length: 1 + Math.floor(rand() * 6) }, () => word(alphabet, 5))];
}
